(()=>{
const M=CivicModel,root=$('#civic-section');
let feed={topics:[],results:{}},feedError='',editing=null,progress=null;
const option=(value,label=value)=>`<option value="${esc(value)}">${esc(label)}</option>`;
$('#civic-scope').innerHTML=option('全部')+M.scopes.map(s=>option(s)).join('');
$('#civic-edit-scope').innerHTML=M.scopes.map(s=>option(s)).join('');
const topics=()=>[...new Map([...(feed.topics||[]),...issues.filter(i=>i.kind==='civic')].map(i=>[i.id,i])).values()];
function editable(id){let item=issues.find(i=>i.id===id);if(!item){item=structuredClone(topics().find(i=>i.id===id));if(!item)throw Error('找不到議題');issues.push(item)}return item}
const linksHtml=links=>(links||[]).filter(l=>M.safeUrl(l.url)).map(l=>`<a class="source-link" href="${esc(M.safeUrl(l.url))}" target="_blank" rel="noopener noreferrer">↗ ${esc(l.title||l.url)}</a>`).join('');
window.renderCivic=function(){
 const opened=new Set([...root.querySelectorAll('details[open]')].map(d=>d.dataset.detail));
 const q=M.normalize($('#civic-search').value),scope=$('#civic-scope').value;
 const list=topics().filter(i=>(scope==='全部'||i.scope===scope)&&M.normalize(i.name+' '+i.scope+' '+i.keys.join(' ')+' '+i.note).includes(q));
 $('#civic-feed-status').textContent=feedError||'新聞推薦'+(feed.updated?'最近檢查：'+new Date(feed.updated).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):'尚未更新')+' · 排程更新及「抓取最新影片」會一併檢查；新增關鍵字將在下次更新後取得新聞。';
 $('#civic-topics').innerHTML=list.map(i=>{
  const result=feed.results?.[i.id],recommendations=M.recommendations(i,result?.items||[],videos);
  const entries=[...(i.entries||[])].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));
  return `<div class="civic-topic" data-topic="${esc(i.id)}"><div class="civic-title"><div><span class="civic-badge">${esc(i.scope)} · ${esc(i.status)}</span><h3>${esc(i.name)}</h3></div><button data-civic-edit="${esc(i.id)}">編輯追蹤方向</button></div><p>${esc(i.note||i.then)}</p><div class="meta"><span>${esc(i.keys.join(' · '))}</span><span>${entries.length} 筆紀錄</span><span>${entries.length?'最近紀錄 '+esc(entries[0].date):'尚無進展紀錄'}</span></div><h4>我關注的具體進展</h4><ol class="civic-criteria">${(i.criteria||[]).map(c=>`<li><span>${esc(c.text)}</span><button data-civic-progress="${esc(c.id)}" data-owner="${esc(i.id)}">${esc(c.status)} · 記錄</button></li>`).join('')}</ol><p class="muted">進度由你依來源判斷並記錄；「待查證」不表示尚未發生。</p><div class="civic-actions"><button data-civic-entry="${esc(i.id)}">＋ 記事／文章／影片連結</button></div><div class="civic-columns"><div><h4>追蹤時間軸</h4>${entries.length?`<details data-detail="timeline:${esc(i.id)}" ${opened.has('timeline:'+i.id)?'open':''}><summary>${entries.length} 筆記事與來源 · 展開查看</summary>${entries.map(e=>`<div class="civic-entry"><div class="meta"><time>${esc(e.date)}</time><span>${esc(e.label)}</span><button data-civic-entry="${esc(i.id)}" data-entry-id="${esc(e.id)}">編輯</button></div>${e.title?`<b>${esc(e.title)}</b>`:''}<p>${esc(e.text)}</p>${linksHtml(e.links)}</div>`).join('')}</details>`:'<p class="muted">先記下關注方向；有新消息時，附上來源與你的觀察。</p>'}</div><div><h4>相關文章與影片推薦</h4><p class="muted">${result?.error?'本次新聞抓取失敗，保留先前推薦。':result?'依關鍵字篩選的公開新聞與現有影片。':'這個議題尚無新聞推薦，等待下次更新。'}${result?.updated?' 新聞取得於 '+esc(date(result.updated))+'。':''}</p>${recommendations.length?recommendations.map((item,index)=>`<div class="civic-recommendation"><div class="meta"><span>${esc(item.type||'文章')} · ${esc(item.source||'公開新聞')}</span><time>${Number.isFinite(Date.parse(item.published))?esc(date(item.published)):'日期未提供'}</time></div><a href="${esc(M.safeUrl(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a><button data-civic-collect="${index}" data-owner="${esc(i.id)}">＋ 收錄到記事</button></div>`).join(''):'<p class="muted">目前沒有符合關鍵字的推薦。你仍可自行新增文章或影片連結。</p>'}</div></div></div>`;
 }).join('')||'<p class="civic-empty muted">這個範圍還沒有議題。按「＋ 新增議題」開始追蹤。</p>';
 root.querySelectorAll('[data-civic-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.civicEdit));
 root.querySelectorAll('[data-civic-entry]').forEach(b=>b.onclick=()=>{editable(b.dataset.civicEntry);openEntry(b.dataset.civicEntry,b.dataset.entryId)});
 root.querySelectorAll('[data-civic-progress]').forEach(b=>b.onclick=()=>openProgress(b.dataset.owner,b.dataset.civicProgress));
 root.querySelectorAll('[data-civic-collect]').forEach(b=>b.onclick=()=>{
  const item=editable(b.dataset.owner),recommendation=M.recommendations(item,feed.results?.[item.id]?.items||[],videos)[Number(b.dataset.civicCollect)];
  openEntry(item.id);$('#entry-note-title').value=recommendation.title;$('#entry-links').value=recommendation.title+' | '+recommendation.url;$('#entry-text').value='來源重點：\n\n與追蹤方向的關聯：';
 });
};
function openEditor(id){editing=id||null;const i=id?topics().find(i=>i.id===id):null;$('#civic-editor-title').textContent=i?'編輯公共議題':'新增公共議題';$('#civic-name').value=i?.name||'';$('#civic-edit-scope').value=i?.scope||'中央';$('#civic-keys').value=(i?.keys||[]).join(', ');$('#civic-note').value=i?.note||'';$('#civic-criteria').value=(i?.criteria||[]).map(c=>c.text).join('\n');$('#civic-status').value=i?.status||'觀察中';$('#civic-editor').showModal()}
$('#civic-add').onclick=()=>openEditor();$('#civic-cancel').onclick=()=>$('#civic-editor').close();
$('#civic-form').onsubmit=e=>{e.preventDefault();const keys=$('#civic-keys').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean),name=$('#civic-name').value.trim(),lines=$('#civic-criteria').value;if(!name||!keys.length||!lines.trim())return;const i=editing?editable(editing):{id:crypto.randomUUID(),kind:'civic',entries:[],then:''};Object.assign(i,{name,scope:$('#civic-edit-scope').value,keys,note:$('#civic-note').value.trim(),status:$('#civic-status').value,criteria:M.criteria(lines,i.criteria||[],()=>crypto.randomUUID())});if(!editing)issues.push(i);save();$('#civic-editor').close();renderIssues();};
const dialog=document.createElement('dialog');dialog.id='civic-progress-editor';dialog.innerHTML=`<form id="civic-progress-form"><h2>記錄指標進展</h2><p id="civic-progress-title"></p><label>狀態<select id="civic-progress-state">${M.states.map(s=>option(s)).join('')}</select></label><label>日期<input id="civic-progress-date" type="date" required></label><label>觀察與依據<textarea id="civic-progress-note" rows="3" required></textarea></label><label>佐證連結（每行：名稱 | 網址；標記已達成時必填）<textarea id="civic-progress-links" rows="3"></textarea></label><p id="civic-progress-error" role="alert"></p><button type="button" id="civic-progress-cancel">取消</button> <button type="submit">儲存進展</button></form>`;document.body.append(dialog);
function openProgress(id,cid){progress={id,cid};const c=topics().find(i=>i.id===id).criteria.find(c=>c.id===cid);$('#civic-progress-title').textContent=c.text;$('#civic-progress-state').value=c.status;$('#civic-progress-date').value=today();$('#civic-progress-note').value='';$('#civic-progress-links').value='';$('#civic-progress-error').textContent='';dialog.showModal()}
$('#civic-progress-cancel').onclick=()=>dialog.close();
$('#civic-progress-form').onsubmit=e=>{e.preventDefault();const links=[];for(const line of $('#civic-progress-links').value.split('\n').filter(s=>s.trim())){const pos=line.indexOf('|'),url=M.safeUrl((pos<0?line:line.slice(pos+1)).trim());if(!url){$('#civic-progress-error').textContent='請輸入有效的 http 或 https 來源連結。';return}links.push({title:pos<0?url:line.slice(0,pos).trim()||url,url})}const status=$('#civic-progress-state').value;if(status==='已達成'&&!links.length){$('#civic-progress-error').textContent='標記已達成前，請附至少一個佐證來源。';return}const i=editable(progress.id),c=i.criteria.find(c=>c.id===progress.cid),previous=c.status;c.status=status;c.updatedAt=new Date().toISOString();i.entries.push({id:crypto.randomUUID(),issueIds:[i.id],date:$('#civic-progress-date').value,createdAt:new Date().toISOString(),label:'進度紀錄',title:c.text,text:previous+' → '+status+'\n'+$('#civic-progress-note').value.trim(),links,country:'tw',region:'asia'});save();dialog.close();renderIssues()};
$('#civic-scope').onchange=window.renderCivic;$('#civic-search').oninput=window.renderCivic;
$('#civic-sync-settings').onclick=()=>$('#sync-settings').click();
const syncStatus=()=>{$('#civic-sync-status').textContent=$('#sync-message').textContent||'編輯先存於本機；設定 GitHub 權杖後自動同步。'};
new MutationObserver(syncStatus).observe($('#sync-message'),{childList:true,subtree:true,characterData:true});syncStatus();
let loading=false;
window.loadCivicRecommendations=async()=>{if(loading)return;loading=true;try{const r=await fetch('public-news.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.topics)||!data.results)throw Error();feed=data;feedError=''}catch{feedError='新聞推薦暫時讀取失敗；保留已載入的內容。請按上方「重新載入頁面資料」重試。'}finally{loading=false;window.renderCivic()}};
window.renderCivic();window.loadCivicRecommendations();
})();
